package br.com.brindespro.quote;
import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import javax.xml.XMLConstants;import javax.xml.parsers.DocumentBuilderFactory;import org.w3c.dom.*;import java.nio.file.*;import java.util.*;import java.io.*;
@RestController @RequestMapping("/api/files") public class FileController {private final QuoteFileRepository files;private final Path folder;public FileController(QuoteFileRepository files,@Value("${app.upload-dir}") String folder){this.files=files;this.folder=Path.of(folder).toAbsolutePath().normalize();}public record Uploaded(Long id,String token){}
 @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Uploaded upload(@RequestParam MultipartFile file)throws IOException{if(file.isEmpty()||file.getSize()>5*1024*1024)throw new IllegalArgumentException("Arquivo deve ter até 5 MB.");byte[] bytes=file.getBytes();String type=detect(bytes);String ext=switch(type){case "image/png"->".png";case "image/jpeg"->".jpg";case "application/pdf"->".pdf";default->".svg";};Files.createDirectories(folder);String name=UUID.randomUUID()+ext;Files.write(folder.resolve(name),bytes,StandardOpenOption.CREATE_NEW);String original=Optional.ofNullable(file.getOriginalFilename()).orElse("arte" ).replaceAll("[^a-zA-Z0-9._-]","_");QuoteFile stored=files.save(new QuoteFile(name,original,type,bytes.length));return new Uploaded(stored.id,stored.uploadToken);}
 private String detect(byte[] b){if(b.length>=8&&(b[0]&255)==137&&b[1]==80&&b[2]==78&&b[3]==71&&b[4]==13&&b[5]==10&&b[6]==26&&b[7]==10)return "image/png";if(b.length>=3&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255)return "image/jpeg";if(b.length>=5&&new String(b,0,5,java.nio.charset.StandardCharsets.US_ASCII).equals("%PDF-"))return "application/pdf";String xml=new String(b,java.nio.charset.StandardCharsets.UTF_8);if(xml.contains("<svg")&&safeSvg(b))return "image/svg+xml";throw new IllegalArgumentException("Formato de arquivo inválido.");}
 private boolean safeSvg(byte[] b){try{DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);f.setFeature("http://xml.org/sax/features/external-general-entities",false);f.setFeature("http://xml.org/sax/features/external-parameter-entities",false);f.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING,true);f.setXIncludeAware(false);f.setExpandEntityReferences(false);Document d=f.newDocumentBuilder().parse(new ByteArrayInputStream(b));if(!d.getDocumentElement().getNodeName().equals("svg"))return false;return validNode(d.getDocumentElement());}catch(Exception e){return false;}}
 private boolean validNode(Node node){Set<String> tags=Set.of("svg","g","path","rect","circle","ellipse","line","polyline","polygon","text","tspan");Set<String> attrs=Set.of("xmlns","viewBox","width","height","x","y","x1","x2","y1","y2","cx","cy","r","rx","ry","d","points","fill","stroke","stroke-width","opacity","transform","font-family","font-size","font-weight","text-anchor","version");if(node.getNodeType()==Node.TEXT_NODE)return true;if(node.getNodeType()!=Node.ELEMENT_NODE||!tags.contains(node.getNodeName()))return false;NamedNodeMap attributes=node.getAttributes();for(int i=0;i<attributes.getLength();i++){Node a=attributes.item(i);if(!attrs.contains(a.getNodeName())||a.getNodeValue().toLowerCase(Locale.ROOT).contains("url("))return false;}NodeList children=node.getChildNodes();for(int i=0;i<children.getLength();i++){if(!validNode(children.item(i)))return false;}return true;}
 @GetMapping("/{id}") public ResponseEntity<byte[]> download(@PathVariable Long id)throws IOException{QuoteFile f=files.findById(id).orElseThrow();byte[] bytes=Files.readAllBytes(folder.resolve(f.storedName));return ResponseEntity.ok().contentType(MediaType.parseMediaType(f.mimeType)).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+f.originalName+"\"").header("X-Content-Type-Options","nosniff").body(bytes);}
}
